<?php require __DIR__.'/config.php';$pdo=db();$exists=(int)$pdo->query("SELECT COUNT(*) FROM admins")->fetchColumn()>0;$message='';if(!$exists){verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$u=trim($_POST['username']??'');$p=$_POST['password']??'';if(strlen($u)<4||strlen($p)<12)$message='Username must be at least 4 characters and password at least 12 characters.';else{$s=$pdo->prepare("INSERT INTO admins(username,password_hash) VALUES(?,?)");$s->execute([$u,password_hash($p,PASSWORD_DEFAULT)]);$message='Admin created. Delete setup-admin.php now and sign in at /admin/login.php.';$exists=true;}}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Initial Admin Setup</title><link rel="stylesheet" href="assets/css/admin.css"></head><body class="login-body"><div class="login-card"><h1>Initial Admin Setup</h1><?php if($exists): ?><div class="notice">An admin account already exists or setup is complete. Delete this file for security.</div><a href="admin/login.php">Go to admin login →</a><?php else: ?><?php if($message): ?><div class="notice"><?=e($message)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Admin username<input name="username" required minlength="4"></label><label>Strong password<input type="password" name="password" required minlength="12"></label><button class="btn primary full">Create admin account</button></form><?php endif; ?></div></body></html>